<?php
require_once __DIR__.'/app.php';$u=require_login();$orderId=value_int($_GET['id']??null);
if(!$orderId){http_response_code(404);exit('Không tìm thấy đơn.');}
$st=db()->prepare('SELECT o.*,customer.full_name customer_name,customer.email customer_email,staff.full_name staff_name FROM orders o JOIN users customer ON customer.id=o.user_id LEFT JOIN users staff ON staff.id=o.assigned_to WHERE o.id=?');$st->execute([$orderId]);$order=$st->fetch();
if(!$order){http_response_code(404);exit('Không tìm thấy đơn.');}
$own=(int)$order['user_id']===(int)$u['id'];
if(!order_scope_allows($order,$u)){http_response_code(403);require __DIR__.'/403.php';exit;}
$st=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$st->execute([$orderId]);$items=$st->fetchAll();
$st=db()->prepare('SELECT ev.*,u.full_name actor_name FROM order_events ev LEFT JOIN users u ON u.id=ev.actor_id WHERE ev.order_id=? ORDER BY ev.id');$st->execute([$orderId]);$events=$st->fetchAll();
$staffOptions=[];foreach(['confirmed','packing','shipped','delivered','cancelled'] as $next)if(allowed_transition($order['status'],$next))$staffOptions[]=$next;
$canProcess=may_process_order($order,$u);
$canAssign=shop_manager($u)&&can('orders.assign')&&in_array($order['status'],['placed','confirmed','packing','shipped'],true);
$employees=[];$assignments=[];
if(shop_manager($u)&&can('orders.view_all')) {
 $employees=db()->query("SELECT u.id,u.full_name,u.email FROM users u JOIN roles r ON r.id=u.role_id WHERE r.code='employee' AND u.is_active=1 ORDER BY u.full_name")->fetchAll();
 $st=db()->prepare('SELECT a.*,from_u.full_name old_name,to_u.full_name new_name,by_u.full_name actor_name FROM order_assignments a LEFT JOIN users from_u ON from_u.id=a.old_employee_id LEFT JOIN users to_u ON to_u.id=a.new_employee_id LEFT JOIN users by_u ON by_u.id=a.actor_id WHERE a.order_id=? ORDER BY a.id DESC');$st->execute([$orderId]);$assignments=$st->fetchAll();
}

$pageTitle='Chi tiết đơn hàng';require __DIR__.'/partials/header.php'; ?>
<div class="page-head"><div><div class="eyebrow">ORDER #<?= (int)$order['id'] ?></div><h1>Chi tiết đơn #<?= (int)$order['id'] ?></h1><p>Đặt lúc <?= h($order['created_at']) ?> · <span class="badge <?= h(status_class($order['status'])) ?>"><?= h(status_name($order['status'])) ?></span></p></div><a href="<?= role_is($u,'customer')?'my_orders.php':'orders.php' ?>" class="btn outline">← Danh sách đơn</a></div>
<div class="two-col"><section class="panel"><div class="panel-head"><h2>Sản phẩm đã đặt</h2></div><div class="table-wrap"><table><thead><tr><th>Sách</th><th>Đơn giá</th><th>SL</th><th>Thành tiền</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= h($item['book_title']) ?></td><td><?= money($item['unit_price']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= money((float)$item['unit_price']*(int)$item['quantity']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="total-line"><span>Giá trị đơn hàng</span><strong><?= money($order['total_amount']) ?></strong></div></section>
<section class="panel"><div class="panel-head"><h2>Thông tin giao hàng</h2></div><dl class="detail-list"><div><dt>Người nhận</dt><dd><?= h($order['shipping_name']) ?></dd></div><div><dt>Điện thoại</dt><dd><?= h($order['shipping_phone']) ?></dd></div><div><dt>Địa chỉ</dt><dd><?= h($order['shipping_address']) ?></dd></div><div><dt>Ghi chú</dt><dd><?= h($order['customer_note']?:'Không có') ?></dd></div><div><dt>Thanh toán</dt><dd>COD (mô phỏng)</dd></div><?php if(!role_is($u,'customer')): ?><div><dt>Tài khoản đặt</dt><dd><?= h($order['customer_name']) ?> (<?= h($order['customer_email']) ?>)</dd></div><div><dt>Nhân viên được giao</dt><dd><?= h($order['staff_name']?:'Chưa phân công') ?></dd></div><?php endif; ?></dl></section></div>
<div class="two-col"><section class="panel"><div class="panel-head"><h2>Tiến độ đơn hàng</h2></div><div class="timeline"><?php foreach($events as $ev): ?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= h(status_name($ev['new_status'])) ?></strong><div class="muted small"><?= h($ev['created_at']) ?> · <?= h($ev['actor_name']?:'Hệ thống') ?></div><?php if($ev['note']):?><div class="small"><?= h($ev['note']) ?></div><?php endif; ?></div></div><?php endforeach; ?></div></section>
<section class="panel"><div class="panel-head"><h2>Thao tác trạng thái</h2></div>
<?php if($canProcess&&$staffOptions): ?><p class="muted small">Mỗi trạng thái chỉ được chuyển theo quy trình. Đơn hủy trước khi giao tự hoàn tồn kho.</p><form method="post" action="order_status.php" class="stack"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$orderId ?>"><label>Trạng thái mới<select name="status" required><?php foreach($staffOptions as $next): ?><option value="<?= h($next) ?>"><?= h(status_name($next)) ?></option><?php endforeach; ?></select></label><label>Ghi chú xử lý<input name="note" maxlength="200" placeholder="Ví dụ: Đã kiểm tra và đóng gói"></label><button class="btn primary">Cập nhật trạng thái</button></form>
<?php elseif(role_is($u,'customer')&&$own&&can('orders.own')&&allowed_transition($order['status'],'cancelled',true)): ?><p class="muted">Bạn có thể hủy đơn khi còn ở trạng thái <strong>Chờ xác nhận</strong>.</p><form method="post" action="order_status.php"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$orderId ?>"><input type="hidden" name="status" value="cancelled"><button class="btn danger">Hủy đơn hàng</button></form>
<?php else: ?><div class="notice">Không có thao tác khả dụng ở trạng thái hiện tại.</div><?php endif; ?></section></div>
<?php if(shop_manager($u)&&can('orders.view_all')): ?>
<div class="two-col"><section class="panel assignment-panel"><div class="panel-head"><h2>Phân công xử lý đơn</h2></div><div class="notice">Manager/Admin phân công cho Employee đang hoạt động. Đơn đã giao hoặc đã hủy không được phân công lại.</div>
<?php if($canAssign):?><form method="post" action="order_assign.php" class="stack"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$orderId ?>"><label>Nhân viên phụ trách<select name="employee_id"><option value="0">— Chưa phân công —</option><?php foreach($employees as $emp):?><option value="<?= (int)$emp['id'] ?>" <?= (int)$order['assigned_to']===(int)$emp['id']?'selected':'' ?>><?= h($emp['full_name']) ?> (<?= h($emp['email']) ?>)</option><?php endforeach;?></select></label><button class="btn primary">Lưu phân công</button></form><?php else:?><div class="notice">Đơn không còn ở trạng thái cho phép phân công.</div><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Lịch sử phân công</h2></div><?php if(!$assignments):?><p class="muted">Chưa có lịch sử phân công.</p><?php else:?><div class="timeline"><?php foreach($assignments as $row):?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= h($row['old_name']?:'Chưa phân công') ?> → <?= h($row['new_name']?:'Chưa phân công') ?></strong><div class="small muted"><?= h($row['created_at']) ?> · <?= h($row['actor_name']?:'Hệ thống') ?></div></div></div><?php endforeach;?></div><?php endif;?></section></div>
<?php endif; ?>
<?php require __DIR__.'/partials/footer.php'; ?>
